// The package that *declares* the generics. Every instantiation of them is
// defined here and carries this package's prefix, whichever package asked.

export const pick = <T>(a: T, b: T): T => a;

export class Holder<T> {
  value: T;

  constructor(value: T) {
    this.value = value;
  }

  get(): T {
    return this.value;
  }
}
